"""`harness fill` subcommand body.

Auto-fills the TODO slots in `*-patterns` skill bodies by invoking the user's
local Claude Code CLI. Harness owns the slot structure; Claude fills the content
within those slots.

Scope:
- Only `<framework>-patterns` skills are eligible. Other skill bodies have
  project-specific intent and stay scaffold-only.
- Target must be `claude-code` (the only emitter shipping today).
- `claude` CLI must be on PATH.
"""

from __future__ import annotations

import difflib
import shutil
import subprocess
from pathlib import Path

import questionary
from rich.console import Console
from ruamel.yaml import YAML

_console = Console()
_err = Console(stderr=True)

_PATTERNS_SUFFIX = "-patterns"
_CLAUDE_TIMEOUT_SECONDS = 600  # 10 min upper bound; complex stacks may need most of it


def _load_harness_config(config_path: Path) -> dict | None:
    """Load harness.yaml as a dict. Returns None on missing or malformed."""
    if not config_path.exists():
        return None
    yaml = YAML()
    with config_path.open(encoding="utf-8") as f:
        return yaml.load(f)


def _find_stack(cfg: dict, framework: str) -> dict | None:
    """Find the stack entry matching `<framework>-patterns` skill."""
    for s in cfg.get("stacks", []) or []:
        if s.get("framework") == framework:
            return s
    return None


def _build_prompt(framework: str, stack: dict | None, body: str) -> str:
    """Compose the prompt for `claude -p`."""
    if stack:
        version = stack.get("version", "(unspecified)")
        pm = stack.get("package_manager") or "(unspecified)"
        tr = stack.get("test_runner") or "(unspecified)"
        paths = stack.get("paths") or ["**"]
        ctx_block = (
            f"- Framework: {framework} {version}\n"
            f"- Package manager: {pm}\n"
            f"- Test runner: {tr}\n"
            f"- Paths: {', '.join(paths)}\n"
        )
    else:
        ctx_block = (
            f"- Framework: {framework} (not declared in harness.yaml; assume latest stable)\n"
        )

    return (
        f"You are filling a Claude Code skill body for the '{framework}' stack. "
        f"The skill is at `.claude/skills/{framework}-patterns/SKILL.md` in the user's project.\n"
        f"\n"
        f"Project context:\n"
        f"{ctx_block}"
        f"\n"
        f"Slot template (DO NOT remove sections, DO NOT add new top-level `## ` sections, "
        f"DO NOT edit frontmatter):\n"
        f"\n"
        f"```markdown\n"
        f"{body}\n"
        f"```\n"
        f"\n"
        f"Replace each `<!-- TODO ... -->` marker with current best-practice content for "
        f"this stack. Match the project context above.\n"
        f"\n"
        f"Constraints:\n"
        f"- Keep body ≤ 150 non-blank lines.\n"
        f"- Use bullet lists; no prose paragraphs.\n"
        f"- Frontmatter (between `---` lines at the top) stays EXACTLY as-is.\n"
        f"- One BAD/GOOD code-pair per section where applicable, ≤ 8 lines each.\n"
        f"- Do not invent versions, deps, or tools not implied by the project context.\n"
        f"\n"
        f"Output ONLY the filled SKILL.md content, starting with the frontmatter `---` line "
        f"and ending with the last content line. No commentary, no fenced backticks around "
        f"the whole document, no `Here is the filled body:` preamble.\n"
    )


def _strip_fence(text: str) -> str:
    """If the output is wrapped in a single ```markdown fence, strip it."""
    lines = text.strip().splitlines()
    if not lines:
        return text
    if lines[0].startswith("```") and lines[-1].startswith("```"):
        return "\n".join(lines[1:-1]) + "\n"
    return text


def _has_frontmatter(text: str) -> bool:
    """Returns True if text starts with a YAML frontmatter block (---...---)."""
    s = text.lstrip()
    if not s.startswith("---"):
        return False
    parts = s.split("---", 2)
    return len(parts) >= 3


def _show_diff(old: str, new: str, path: Path) -> None:
    """Print a unified diff between old and new content."""
    diff = difflib.unified_diff(
        old.splitlines(keepends=True),
        new.splitlines(keepends=True),
        fromfile=f"a/{path}",
        tofile=f"b/{path}",
        n=3,
    )
    for line in diff:
        if line.startswith("+++") or line.startswith("---"):
            _console.print(f"[bold]{line}[/bold]", end="")
        elif line.startswith("+"):
            _console.print(f"[green]{line}[/green]", end="")
        elif line.startswith("-"):
            _console.print(f"[red]{line}[/red]", end="")
        elif line.startswith("@"):
            _console.print(f"[cyan]{line}[/cyan]", end="")
        else:
            _console.print(line, end="")


def _list_patterns_skills(project_dir: Path) -> list[Path]:
    """Return all `<name>-patterns/SKILL.md` paths under .claude/skills/."""
    skills_dir = project_dir / "skills"
    if not skills_dir.is_dir():
        return []
    return [
        p / "SKILL.md"
        for p in skills_dir.iterdir()
        if p.is_dir() and p.name.endswith(_PATTERNS_SUFFIX)
        and (p / "SKILL.md").is_file()
    ]


def _fill_one(
    skill_path: Path,
    cfg: dict,
    *,
    yes: bool,
    dry_run: bool,
) -> int:
    """Fill a single SKILL.md via Claude CLI. Returns 0 on success, non-zero on failure."""
    skill_name = skill_path.parent.name  # e.g. `nextjs-patterns`
    framework = skill_name.removesuffix(_PATTERNS_SUFFIX)
    body = skill_path.read_text(encoding="utf-8")

    if "<!-- TODO" not in body:
        _console.print(
            f"[dim]{skill_name}: no TODO markers — skipping.[/dim]"
        )
        return 0

    stack = _find_stack(cfg, framework)
    prompt = _build_prompt(framework, stack, body)

    _console.print(f"[dim]invoking `claude -p` for {skill_name}…[/dim]")
    try:
        result = subprocess.run(
            # Remove file-mutation tools from the model's context so it cannot try
            # to WRITE the skill file (which blocks pending approval in headless
            # `-p` mode and emits no document). With no edit tools, the model
            # satisfies the prompt by PRINTING the filled SKILL.md to stdout —
            # which is what fill parses and writes itself. Per CLI reference, a
            # bare tool name in --disallowedTools removes that tool from context.
            ["claude", "-p", prompt, "--output-format", "text",
             "--disallowedTools", "Write", "Edit", "NotebookEdit"],
            capture_output=True,
            text=True,
            timeout=_CLAUDE_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        _err.print(
            f"[red]{skill_name}: claude CLI timed out after {_CLAUDE_TIMEOUT_SECONDS}s.[/red]"
        )
        return 1
    except FileNotFoundError:
        _err.print("[red]claude CLI not found on PATH. Install: https://claude.ai/download[/red]")
        return 1

    if result.returncode != 0:
        _err.print(
            f"[red]{skill_name}: claude CLI returned {result.returncode}:[/red]\n"
            f"{result.stderr or result.stdout}"
        )
        return result.returncode

    new_body = _strip_fence(result.stdout.strip()) + "\n"

    if not _has_frontmatter(new_body):
        _err.print(
            f"[red]{skill_name}: claude output is missing the frontmatter. "
            f"Refusing to write. Re-run, or hand-edit the skill.[/red]"
        )
        return 1

    _show_diff(body, new_body, skill_path)

    if dry_run:
        _console.print(f"[dim]{skill_name}: --dry-run, not writing.[/dim]")
        return 0

    if not yes:
        ok = questionary.confirm(
            f"Write filled body to {skill_path}?", default=True
        ).unsafe_ask()
        if not ok:
            _console.print(f"[dim]{skill_name}: declined, not writing.[/dim]")
            return 0

    skill_path.write_text(new_body, encoding="utf-8")
    _console.print(f"[green]{skill_name}: wrote {skill_path}.[/green]")
    return 0


def cmd_fill(
    skill_name: str | None,
    *,
    all_patterns: bool = False,
    yes: bool = False,
    dry_run: bool = False,
    project_dir: Path = Path(".claude"),
    config_path: Path = Path("harness.yaml"),
) -> int:
    """Fill the TODO slots in one or many `<framework>-patterns` skills.

    Args:
        skill_name: required when `all_patterns` is False. Must end with `-patterns`.
        all_patterns: when True, iterates every `<name>-patterns` skill that has
            unfilled TODO markers.
        yes: skip the confirm prompt before writing.
        dry_run: invoke Claude CLI + show diff but never write.
        project_dir: path to `.claude/`.
        config_path: path to `harness.yaml`.

    Returns: 0 on full success, non-zero on first failure.
    """
    # Validate args
    if all_patterns and skill_name:
        _err.print("[red]Pass either <skill-name> or --all, not both.[/red]")
        return 1
    if not all_patterns and not skill_name:
        _err.print("[red]Pass a <skill-name> or --all.[/red]")
        return 1

    # Validate config
    cfg = _load_harness_config(config_path)
    if cfg is None:
        _err.print(
            f"[red]{config_path} not found or unreadable. "
            f"Run `harness init` then `harness generate` first.[/red]"
        )
        return 1
    targets = cfg.get("targets") or ["claude-code"]
    if targets != ["claude-code"]:
        _err.print(
            f"[red]`harness fill` currently supports the claude-code target only "
            f"(found: {targets}).[/red]"
        )
        return 1

    # Validate claude CLI
    if shutil.which("claude") is None:
        _err.print(
            "[red]`claude` CLI not on PATH. Install: https://claude.ai/download[/red]"
        )
        return 1

    # Resolve target skill(s)
    if all_patterns:
        skills = _list_patterns_skills(project_dir)
        if not skills:
            _console.print(
                "[dim]No `*-patterns` skills found under .claude/skills/. "
                "Run `harness add stack <name>:<version>` first.[/dim]"
            )
            return 0
    else:
        if not skill_name.endswith(_PATTERNS_SUFFIX):
            _err.print(
                f"[red]`harness fill` only supports `*-patterns` skills. "
                f"Got: {skill_name!r}.[/red]"
            )
            return 1
        skill_path = project_dir / "skills" / skill_name / "SKILL.md"
        if not skill_path.is_file():
            _err.print(
                f"[red]Skill not found at {skill_path}. "
                f"Run `harness add stack {skill_name.removesuffix(_PATTERNS_SUFFIX)}:<version>` "
                f"first.[/red]"
            )
            return 1
        skills = [skill_path]

    # Fill each
    for path in skills:
        rc = _fill_one(path, cfg, yes=yes, dry_run=dry_run)
        if rc != 0:
            return rc
    return 0
